<?php
namespace App\Http\Controllers\Api\V1;
use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Password; use Illuminate\Support\Str;
final class PasswordController { public function forgot(Request $request): JsonResponse { $request->validate(['email'=>['required','email']]); Password::sendResetLink(['email'=>$request->string('email')->toString()]); return response()->json(['message'=>'If an account matches, reset instructions will be sent.']); } public function reset(Request $request): JsonResponse { $data=$request->validate(['token'=>['required'],'email'=>['required','email'],'password'=>['required','string','min:12','confirmed']]); $status=Password::reset($data,function($user,$password){$user->forceFill(['password'=>Hash::make($password),'remember_token'=>Str::random(60),'account_status'=>$user->account_status==='suspended'?'suspended':'active'])->save();}); return $status===Password::PASSWORD_RESET ? response()->json(['message'=>'Password reset.']) : response()->json(['message'=>'Unable to reset password.'],422); } }
